<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {http,dataOf} from '../api/http'
import {useAuthStore} from '../stores/auth'

const route=useRoute(),auth=useAuthStore()
const entities=ref<any[]>([]),graph=ref<any>({nodes:[],edges:[]}),root=ref<number>(),direction=ref('both'),depth=ref(6),loading=ref(false),keyword=ref('')
const selectedNode=ref<any>(),evidence=ref<any>({attachments:[],auditEvents:[],attachmentTotal:0,auditTotal:0}),evidenceLoading=ref(false),activeTab=ref('catalog')
const nodeWidth=204,nodeHeight=86

async function loadEntities(){entities.value=dataOf(await http.get('/trace/entities',{params:{keyword:keyword.value}}))}
async function trace(){if(!root.value)return;loading.value=true;try{graph.value=dataOf(await http.get(`/trace/graph/${root.value}`,{params:{direction:direction.value,maxDepth:depth.value}}));const node=graph.value.nodes?.find((item:any)=>Number(item.id)===Number(root.value));if(node)await selectNode(node,false)}finally{loading.value=false}}
async function selectNode(node:any,switchTab=true){selectedNode.value=node;if(switchTab)activeTab.value='evidence';evidenceLoading.value=true;try{evidence.value=dataOf(await http.get(`/trace/entities/${node.id}/evidence`))}finally{evidenceLoading.value=false}}
async function fetchBlob(row:any,preview=false){const blob=await http.get(`/files/${row.id}`,{params:{preview},responseType:'blob'}) as unknown as Blob;const url=URL.createObjectURL(blob);if(preview)window.open(url,'_blank','noopener,noreferrer');else{const link=document.createElement('a');link.href=url;link.download=row.originalName;link.click()}window.setTimeout(()=>URL.revokeObjectURL(url),60000)}
function typeName(t:string){return({MATERIAL_BATCH:'材料批次',PROCESS_BATCH:'工艺批次',PRODUCT:'产品',QUALITY_INSPECTION:'质量检测',PERFORMANCE_TEST:'性能测试',DEFECT:'质量缺陷'} as any)[t]||t}
function short(value:any,length=22){const text=String(value??'');return text.length>length?text.slice(0,length-1)+'…':text}
function size(value:number){if(value<1024)return value+' B';if(value<1048576)return(value/1024).toFixed(1)+' KB';return(value/1048576).toFixed(1)+' MB'}
function previewable(type:string){return ['text/plain','application/pdf','image/png','image/jpeg','image/gif','image/webp','image/bmp'].includes(String(type).toLowerCase())}
function time(value:any){return String(value||'').replace('T',' ').slice(0,19)}
function detailText(value:any){return Object.entries(value||{}).map(([key,item])=>`${key}=${item}`).join(' · ')}

const visual=computed(()=>{
 const nodes=(graph.value.nodes||[]) as any[],edges=(graph.value.edges||[]) as any[]
 const adjacency=new Map<number,number[]>();for(const node of nodes)adjacency.set(Number(node.id),[])
 for(const edge of edges){const from=Number(edge.from),to=Number(edge.to);if(graph.value.direction==='forward')adjacency.get(from)?.push(to);else if(graph.value.direction==='reverse')adjacency.get(to)?.push(from);else{adjacency.get(from)?.push(to);adjacency.get(to)?.push(from)}}
 const levels=new Map<number,number>(),queue:number[]=[];if(graph.value.rootId){levels.set(Number(graph.value.rootId),0);queue.push(Number(graph.value.rootId))}
 while(queue.length){const current=queue.shift()!,nextLevel=(levels.get(current)||0)+1;for(const next of adjacency.get(current)||[])if(!levels.has(next)){levels.set(next,nextLevel);queue.push(next)}}
 let maxLevel=Math.max(0,...levels.values());for(const node of nodes)if(!levels.has(Number(node.id)))levels.set(Number(node.id),++maxLevel)
 const layers=new Map<number,any[]>();for(const node of nodes){const level=levels.get(Number(node.id))||0;if(!layers.has(level))layers.set(level,[]);layers.get(level)!.push(node)}
 for(const layer of layers.values())layer.sort((a,b)=>String(a.entityCode).localeCompare(String(b.entityCode),'zh-CN'))
 const positions=new Map<number,{x:number,y:number}>();let largest=1
 for(const [level,layer] of layers){largest=Math.max(largest,layer.length);layer.forEach((node,index)=>positions.set(Number(node.id),{x:42+level*258,y:42+index*116}))}
 return{positions,width:Math.max(820,(maxLevel+1)*258+72),height:Math.max(430,largest*116+78)}
})
function edgePath(edge:any){const from=visual.value.positions.get(Number(edge.from)),to=visual.value.positions.get(Number(edge.to));if(!from||!to)return'';let sx=from.x+nodeWidth/2,sy=from.y+nodeHeight/2,tx=to.x+nodeWidth/2,ty=to.y+nodeHeight/2,dx=tx-sx,dy=ty-sy;if(Math.abs(dx)>=Math.abs(dy)){const sign=dx>=0?1:-1;sx+=sign*nodeWidth/2;tx-=sign*nodeWidth/2}else{const sign=dy>=0?1:-1;sy+=sign*nodeHeight/2;ty-=sign*nodeHeight/2}dx=tx-sx;return`M ${sx} ${sy} C ${sx+dx*.42} ${sy}, ${tx-dx*.42} ${ty}, ${tx} ${ty}`}
function edgeLabel(edge:any){const from=visual.value.positions.get(Number(edge.from)),to=visual.value.positions.get(Number(edge.to));return from&&to?{x:(from.x+to.x)/2+nodeWidth/2,y:(from.y+to.y)/2+nodeHeight/2-7}:{x:0,y:0}}

onMounted(async()=>{await loadEntities();if(route.query.root){root.value=Number(route.query.root);await trace()}})
</script>

<template><div class="page"><div class="page-head"><div><h1 class="page-title">全链路追溯</h1><div class="page-subtitle">从材料批次到工艺、产品与质量证据，按数据域展示正向、反向和双向链路</div></div></div>
 <div class="trace-controls surface"><el-select v-model="root" filterable placeholder="选择追溯起点" style="width:330px"><el-option v-for="e in entities" :key="e.id" :label="`${e.entityCode} · ${e.entityName}`" :value="e.id"/></el-select><el-radio-group v-model="direction"><el-radio-button value="forward">正向</el-radio-button><el-radio-button value="both">双向</el-radio-button><el-radio-button value="reverse">反向</el-radio-button></el-radio-group><span class="muted">深度</span><el-input-number v-model="depth" :min="1" :max="10"/><el-button type="primary" @click="trace">开始追溯</el-button></div>
 <div class="trace-layout"><section class="surface graph" v-loading="loading"><div class="graph-head"><div><h3>可视化追溯链</h3><small>单击节点查看附件和不可变审计证据</small></div><span>{{graph.nodes?.length||0}} 节点 · {{graph.edges?.length||0}} 关系</span></div>
  <div v-if="graph.nodes?.length" class="graph-scroll"><svg class="trace-svg" :viewBox="`0 0 ${visual.width} ${visual.height}`" :style="{width:visual.width+'px',height:visual.height+'px'}" role="img" aria-label="追溯关系图"><defs><marker id="trace-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs>
   <g class="edges"><template v-for="edge in graph.edges" :key="edge.id"><path :d="edgePath(edge)" marker-end="url(#trace-arrow)"/><text v-if="graph.edges.length<=80" :x="edgeLabel(edge).x" :y="edgeLabel(edge).y">{{short(edge.type,18)}}</text></template></g>
   <g v-for="node in graph.nodes" :key="node.id" class="svg-node" :class="[{selected:selectedNode?.id===node.id,root:Number(graph.rootId)===Number(node.id)},String(node.entityType).toLowerCase()]" :transform="`translate(${visual.positions.get(Number(node.id))?.x||0} ${visual.positions.get(Number(node.id))?.y||0})`" tabindex="0" role="button" @click="selectNode(node)" @keyup.enter="selectNode(node)"><rect :width="nodeWidth" :height="nodeHeight" rx="11"/><text class="node-type" x="14" y="20">{{typeName(node.entityType)}} · #{{node.id}}</text><text class="node-name" x="14" y="43">{{short(node.entityName,24)}}</text><text class="node-code" x="14" y="62">{{short(node.entityCode,26)}}</text><text class="node-evidence" x="14" y="77">附件 / 审计证据 ›</text></g>
  </svg></div>
  <div v-else class="empty-note"><div class="trace-icon">⌘</div>选择实体并开始追溯，平台将严格按您的数据域展开链路</div>
  <div v-if="graph.edges?.length" class="relation-table"><div class="relation-head"><b>关系证据清单</b><span>关系方向始终保持业务原始方向</span></div><div v-for="edge in graph.edges" :key="edge.id"><span class="mono">#{{edge.from}}</span><b>— {{edge.type}} →</b><span class="mono">#{{edge.to}}</span><time>{{time(edge.effectiveTime)}}</time></div></div>
 </section>
 <aside class="surface side-panel"><el-tabs v-model="activeTab"><el-tab-pane label="实体目录" name="catalog"><el-input v-model="keyword" placeholder="搜索批次或产品" clearable @keyup.enter="loadEntities"><template #append><el-button @click="loadEntities">查询</el-button></template></el-input><div class="entity-list"><button v-for="item in entities" :key="item.id" :class="{active:root===item.id}" @click="root=item.id"><i></i><div><b>{{item.entityName}}</b><span>{{item.entityCode}} · {{typeName(item.entityType)}}</span></div></button></div></el-tab-pane>
  <el-tab-pane label="节点证据" name="evidence"><div v-if="!selectedNode" class="evidence-empty">单击图中节点查看证据</div><div v-else v-loading="evidenceLoading" class="evidence"><div class="selected-title"><small>{{typeName(selectedNode.entityType)}}</small><b>{{selectedNode.entityName}}</b><span class="mono">{{selectedNode.entityCode}}</span></div><div class="evidence-stats"><div><b>{{evidence.attachmentTotal||0}}</b><span>关联附件</span></div><div><b>{{evidence.auditTotal||0}}</b><span>审计事件</span></div></div>
   <section><h4>原始记录与来源</h4><div class="source-record"><dl><div><dt>来源系统</dt><dd>{{evidence.entity?.sourceSystem||'平台录入'}}</dd></div><div><dt>来源记录</dt><dd class="mono">{{evidence.entity?.sourceRecordId||'—'}}</dd></div><div><dt>记录版本</dt><dd>v{{evidence.entity?.version||1}}</dd></div><div><dt>记录时间</dt><dd>{{time(evidence.entity?.createdTime)}}</dd></div></dl><div class="property-list"><span v-if="!Object.keys(evidence.entity?.properties||{}).length" class="mini-empty">暂无结构化业务参数</span><div v-for="(value,key) in evidence.entity?.properties||{}" :key="String(key)"><b>{{key}}</b><span>{{value}}</span></div></div></div></section>
   <section><h4>关联附件</h4><el-alert v-if="!evidence.attachmentAccess" title="当前角色没有附件读取权限" type="info" :closable="false"/><div v-else-if="evidence.attachments?.length" class="attachment-list"><article v-for="file in evidence.attachments" :key="file.id"><div><b>{{file.originalName}}</b><span>{{size(file.sizeBytes)}} · {{file.uploadedByName}} · {{time(file.createdTime)}}</span><code>{{file.sha256}}</code></div><div><el-button v-if="previewable(file.contentType)" link type="primary" @click="fetchBlob(file,true)">预览</el-button><el-button link @click="fetchBlob(file)">下载</el-button></div></article></div><div v-else class="mini-empty">暂无关联附件</div></section>
   <section><h4>不可变审计证据 <small v-if="evidence.auditLimited">（展示最新100条）</small></h4><div v-if="evidence.auditEvents?.length" class="audit-timeline"><article v-for="event in evidence.auditEvents" :key="event.id"><i></i><div><header><b>{{event.description}}</b><time>{{time(event.createdTime)}}</time></header><span>{{event.username}} · {{event.module}}/{{event.operation}}</span><p v-if="detailText(event.details)">{{detailText(event.details)}}</p><code>摘要 {{event.recordDigest}}</code></div></article></div><div v-else class="mini-empty">暂无关联审计事件</div></section>
  </div></el-tab-pane></el-tabs></aside></div></div></template>

<style scoped>
.trace-controls{padding:15px;display:flex;gap:12px;align-items:center;margin-bottom:15px;flex-wrap:wrap}.trace-layout{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:15px}.graph,.side-panel{padding:20px;min-height:620px}.graph-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.graph-head h3{margin:0;font-size:15px}.graph-head small{display:block;color:#8795a5;margin-top:5px}.graph-head>span{font-size:10px;color:#8694a4}.graph-scroll{overflow:auto;border:1px solid #edf2f6;border-radius:12px;background:radial-gradient(#dce5ed 1px,transparent 1px);background-size:18px 18px;min-height:430px}.trace-svg{display:block}.edges path{fill:none;stroke:#9eb5c6;stroke-width:1.7}.edges marker path,#trace-arrow path{fill:#6489a3}.edges text{font-size:9px;fill:#6d8294;text-anchor:middle;paint-order:stroke;stroke:#fff;stroke-width:4px}.svg-node{cursor:pointer;outline:none}.svg-node rect{fill:#fff;stroke:#cfdde7;stroke-width:1.2;filter:drop-shadow(0 5px 9px rgba(35,65,91,.09))}.svg-node:hover rect,.svg-node:focus rect{stroke:#3891b6;stroke-width:2}.svg-node.selected rect{stroke:#1677a8;stroke-width:2.5;fill:#f2f9fc}.svg-node.root rect{stroke-dasharray:5 3}.svg-node.material_batch rect{fill:#f3f9ff}.svg-node.process_batch rect{fill:#faf6ff}.svg-node.product rect{fill:#f1fbf7}.svg-node.quality_inspection rect,.svg-node.performance_test rect{fill:#fff8ef}.svg-node text{pointer-events:none}.node-type{font-size:9px;fill:#397a9b}.node-name{font-size:12px;font-weight:700;fill:#19314b}.node-code{font-size:9px;fill:#74879a;font-family:SFMono-Regular,Consolas,monospace}.node-evidence{font-size:8px;fill:#6c8da3}.relation-table{margin-top:18px;max-height:240px;overflow:auto}.relation-head{display:flex;justify-content:space-between;padding:10px;border-bottom:1px solid #edf1f5}.relation-head span{font-size:9px;color:#8996a5}.relation-table>div:not(.relation-head){display:grid;grid-template-columns:80px 1fr 80px 145px;align-items:center;padding:10px;border-bottom:1px solid #edf1f5;font-size:11px}.relation-table>div>b{font-size:9px;color:#266b98}.relation-table time{color:#8996a5}.trace-icon{font-size:44px;color:#6f9ab6;margin-bottom:10px}.entity-list{margin-top:12px;max-height:515px;overflow:auto}.entity-list button{width:100%;border:0;border-bottom:1px solid #edf1f5;background:none;text-align:left;padding:13px 8px;display:flex;gap:10px;cursor:pointer;border-radius:7px}.entity-list button:hover,.entity-list button.active{background:#eef6fb}.entity-list i{width:8px;height:8px;border-radius:50%;background:#3c95b3;margin-top:5px}.entity-list b,.entity-list span{display:block}.entity-list b{font-size:11px}.entity-list span{font-size:9px;color:#8795a5;margin-top:4px}.evidence-empty,.mini-empty{text-align:center;color:#8b99aa;padding:34px 8px}.selected-title{padding-bottom:13px;border-bottom:1px solid #edf1f5}.selected-title small,.selected-title b,.selected-title span{display:block}.selected-title small{color:#397a9b;font-size:9px}.selected-title b{margin:6px 0;font-size:14px}.selected-title span{font-size:10px;color:#74879a}.evidence-stats{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:14px 0}.evidence-stats div{padding:12px;background:#f6f9fc;border-radius:9px}.evidence-stats b,.evidence-stats span{display:block}.evidence-stats b{font-size:18px;color:#176f9a}.evidence-stats span{font-size:9px;color:#8290a1}.evidence section{margin-top:18px}.evidence h4{font-size:12px;margin:0 0 9px}.evidence h4 small{font-weight:400;color:#8996a5}.source-record{border:1px solid #e7eef4;border-radius:9px;overflow:hidden}.source-record dl{display:grid;grid-template-columns:1fr 1fr;margin:0;background:#f7fafc}.source-record dl>div{padding:8px;border-bottom:1px solid #edf1f5}.source-record dt{font-size:8px;color:#8493a3}.source-record dd{font-size:9px;margin:3px 0 0;word-break:break-all}.property-list{padding:7px 9px}.property-list>div{display:flex;justify-content:space-between;gap:12px;padding:6px 0;border-bottom:1px dashed #edf1f5}.property-list>div:last-child{border-bottom:0}.property-list b,.property-list span{font-size:9px;word-break:break-all}.property-list b{color:#527186}.property-list span{text-align:right}.attachment-list,.audit-timeline{max-height:260px;overflow:auto}.attachment-list article{display:flex;justify-content:space-between;gap:8px;padding:10px 0;border-bottom:1px solid #edf1f5}.attachment-list b,.attachment-list span,.attachment-list code{display:block}.attachment-list b{font-size:10px;word-break:break-all}.attachment-list span{font-size:8px;color:#8795a5;margin:4px 0}.attachment-list code,.audit-timeline code{display:block;font-size:7px;color:#93a0ae;word-break:break-all}.audit-timeline article{display:grid;grid-template-columns:13px 1fr;gap:7px;padding:8px 0}.audit-timeline article>i{width:7px;height:7px;border-radius:50%;background:#318cad;margin-top:5px}.audit-timeline header{display:flex;justify-content:space-between;gap:8px}.audit-timeline header b{font-size:10px}.audit-timeline time,.audit-timeline span{font-size:8px;color:#8795a5}.audit-timeline p{font-size:8px;color:#566b80;margin:4px 0;word-break:break-all}
@media(max-width:1100px){.trace-layout{grid-template-columns:1fr}.side-panel{min-height:420px}.entity-list{max-height:300px}}
</style>
